(function(){
  Game.startWorld(56); Game.player.iFrames=1e9;
  for(let i=0;i<200;i++){ Game.player.iFrames=1e9; Game.debugStep(1,1000/60,false); }
  const P=Game.player;
  const b=Game.enemies.find(e=>!e.dead&&!e.isKeyGhost&&!Game.world.isBush(e.centerX(),e.centerY()));
  b.x=P.x-50; b.y=P.y; b._engaged=true; b.cool=0; b.state='hover'; b.stateT=0;
  const stiche=[]; let alt=b.state, zurueck=0;
  for(let i=0;i<1800;i++){
    Game.player.iFrames=1e9; Game.debugStep(1,1000/60,false);
    // Biene bleibt in Marks Naehe (Engine laesst weit entfernte Gegner ruhen, das misst hier nur falsch)
    if(Math.hypot(b.centerX()-P.x,b.centerY()-P.y)>130){ b.x=P.x-50; b.y=P.y; zurueck++; }
    if(Game.world.isBush(b.centerX(),b.centerY())){ b.x+=(b.centerX()<P.x?-14:14); }
    if(alt!=='stingWind'&&b.state==='stingWind') stiche.push(i);
    alt=b.state;
    if(stiche.length>=7) break;
  }
  const sek=stiche.map(i=>+(i/60).toFixed(2));
  const ab=[]; for(let i=1;i<stiche.length;i++) ab.push(+((stiche[i]-stiche[i-1])/60).toFixed(2));
  return 'Stiche bei Sekunde '+sek.join(', ')+' | Abstand '+ab.join(', ')+' s | alle Abstaende >= 0,9 s: '+
    (ab.length?ab.every(a=>a>=0.9):false)+' | zurueckgeholt '+zurueck+' mal | Zustand am Ende '+b.state;
})()
